// Conformance test: IdentityKeyPair wire-format parity vs Rust libsignal.
//
// Loads the fixture generated by wire_emitter::emit_identity_key_pair and
// verifies that Go's NewKeyPairFromBytes correctly deserializes the
// IdentityKeyPairStructure protobuf, recovering the same public and private
// key bytes that Rust serialized.
//
// Rust upstream: rust/protocol/src/identity_key.rs — IdentityKeyPair::serialize
// and TryFrom<&[u8]> for IdentityKeyPair (libsignal v0.92.2, RUST_REV 98915c442d).

package interop

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"testing"

	"github.com/jeremyhahn/go-libsignal/pkg/keys/identity"
	"github.com/jeremyhahn/go-libsignal/tests/interop/loader"
)

type identityKeyPairWireFixture struct {
	Source  string `json:"source"`
	RustRev string `json:"rust_rev"`
	Purpose string `json:"purpose"`
	Vectors []struct {
		Name   string `json:"name"`
		Inputs struct {
			PublicHex  string `json:"public_hex"`
			PrivateHex string `json:"private_hex"`
		} `json:"inputs"`
		Expected struct {
			SerializedHex string `json:"serialized_hex"`
		} `json:"expected"`
	} `json:"vectors"`
}

// TestIdentityKeyPairWire verifies that Go's NewKeyPairFromBytes/Serialize
// round-trips against the Rust-emitted IdentityKeyPairStructure protobuf.
func TestIdentityKeyPairWire(t *testing.T) {
	data := loader.MustRead("wire/identity_key_pair.json")

	var fixture identityKeyPairWireFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatalf("failed to parse identity_key_pair.json: %v", err)
	}
	if len(fixture.Vectors) == 0 {
		t.Fatal("no vectors in identity_key_pair.json")
	}

	for _, v := range fixture.Vectors {
		v := v
		t.Run(v.Name, func(t *testing.T) {
			wantPub, err := hex.DecodeString(v.Inputs.PublicHex)
			if err != nil {
				t.Fatalf("decode public_hex: %v", err)
			}
			wantPriv, err := hex.DecodeString(v.Inputs.PrivateHex)
			if err != nil {
				t.Fatalf("decode private_hex: %v", err)
			}
			serialized, err := hex.DecodeString(v.Expected.SerializedHex)
			if err != nil {
				t.Fatalf("decode serialized_hex: %v", err)
			}

			kp, err := identity.NewKeyPairFromBytes(serialized)
			if err != nil {
				t.Fatalf("NewKeyPairFromBytes failed: %v", err)
			}

			// The public key serialized form is 33 bytes: 0x05 || 32-byte scalar.
			gotPub := kp.PublicKey().Serialize()
			if !bytes.Equal(gotPub, wantPub) {
				t.Errorf("public key mismatch:\n  got  %x\n  want %x", gotPub, wantPub)
			}

			// The private key is a 32-byte scalar.
			privArr := kp.PrivateKey().Serialize()
			gotPriv := privArr[:]
			if !bytes.Equal(gotPriv, wantPriv) {
				t.Errorf("private key mismatch:\n  got  %x\n  want %x", gotPriv, wantPriv)
			}

			// Verify round-trip: re-serializing must produce identical bytes.
			reSerialized, err := kp.Serialize()
			if err != nil {
				t.Fatalf("Serialize() failed: %v", err)
			}
			if !bytes.Equal(reSerialized, serialized) {
				t.Errorf("re-serialized bytes differ from Rust fixture:\n  got  %x\n  want %x", reSerialized, serialized)
			}
		})
	}
}
